package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
	"time"
)

type trendReportLite struct {
	ManifestName    string       `json:"manifest_name"`
	ManifestVersion string       `json:"manifest_version"`
	OverallStatus   string       `json:"overall_status"`
	Timestamp       string       `json:"timestamp"`
	Steps           []stepReport `json:"steps"`
}

type trendStep struct {
	StepID           string   `json:"step_id"`
	Statuses         []*string `json:"statuses"`
	FirstSeenIndex   int      `json:"first_seen_index"`
	LastSeenIndex    int      `json:"last_seen_index"`
	StatusChanges    int      `json:"status_changes"`
	Stability        float64  `json:"stability"`
	Classification   string   `json:"classification"`
}

type trendAggregate struct {
	TotalStepsTracked int     `json:"total_steps_tracked"`
	StableCount      int     `json:"stable_count"`
	FlakyCount       int     `json:"flaky_count"`
	DegradingCount   int     `json:"degrading_count"`
	ImprovingCount   int     `json:"improving_count"`
	OverallStability float64 `json:"overall_stability"`
}

type trendOutput struct {
	TrendTimestamp string         `json:"trend_timestamp"`
	ReportCount    int            `json:"report_count"`
	StepTrends    []trendStep    `json:"step_trends"`
	Aggregate      trendAggregate `json:"aggregate"`
}

func trendCmd(args []string) {
	format := "json"
	positional := parseFlags(args, map[string]*string{
		"format": &format,
	})

	if len(positional) < 2 {
		fmt.Fprintln(os.Stderr, "error: trend requires at least two report files")
		os.Exit(2)
	}

	reports := make([]*trendReportLite, 0, len(positional))
	for _, path := range positional {
		rep, err := loadTrendReport(path)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(2)
		}
		reports = append(reports, rep)
	}

	output := buildTrendOutput(reports)

	if format == "text" {
		printTrendText(output)
	} else {
		data, err := json.MarshalIndent(output, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			os.Exit(2)
		}
		fmt.Println(string(data))
	}

	if output.Aggregate.DegradingCount > 0 || output.Aggregate.FlakyCount > 0 {
		os.Exit(1)
	}
	os.Exit(0)
}

func loadTrendReport(path string) (*trendReportLite, error) {
	if _, err := os.Stat(path); err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("error: trend file not found: %s", path)
		}
		return nil, fmt.Errorf("error: invalid trend input: %s: %s", path, err)
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("error: invalid trend input: %s: %s", path, err)
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("error: invalid trend input: %s: %s", path, err)
	}

	for _, field := range []string{"manifest_name", "overall_status", "steps"} {
		if _, ok := raw[field]; !ok {
			return nil, fmt.Errorf("error: invalid trend input: %s: missing field %s", path, field)
		}
	}

	var r trendReportLite
	if err := json.Unmarshal(data, &r); err != nil {
		return nil, fmt.Errorf("error: invalid trend input: %s: %s", path, err)
	}
	if r.ManifestName == "" {
		return nil, fmt.Errorf("error: invalid trend input: %s: missing field manifest_name", path)
	}
	if r.OverallStatus == "" {
		return nil, fmt.Errorf("error: invalid trend input: %s: missing field overall_status", path)
	}
	if r.Steps == nil {
		return nil, fmt.Errorf("error: invalid trend input: %s: missing field steps", path)
	}

	return &r, nil
}

func buildTrendOutput(reports []*trendReportLite) *trendOutput {
	reportCount := len(reports)
	stepIDs := make(map[string]bool)
	reportStepStatus := make([]map[string]string, reportCount)

	for i, rep := range reports {
		statusByID := make(map[string]string)
		for _, step := range rep.Steps {
			statusByID[step.ID] = step.Status
			stepIDs[step.ID] = true
		}
		reportStepStatus[i] = statusByID
	}

	ids := make([]string, 0, len(stepIDs))
	for id := range stepIDs {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	stepTrends := make([]trendStep, 0, len(ids))
	var stableCount, flakyCount, degradingCount, improvingCount int
	var stabilitySum float64

	for _, id := range ids {
		statuses := make([]*string, reportCount)
		appearances := 0
		firstSeenIndex := -1
		lastSeenIndex := -1
		var firstStatus, lastStatus string

		for i, statusByID := range reportStepStatus {
			if status, ok := statusByID[id]; ok {
				statusCopy := status
				statuses[i] = &statusCopy
				appearances++
				if firstSeenIndex == -1 {
					firstSeenIndex = i
					firstStatus = status
				}
				lastSeenIndex = i
				lastStatus = status
			}
		}

		statusChanges := 0
		var prev *string
		for _, status := range statuses {
			if status == nil {
				continue
			}
			if prev != nil && *prev != *status {
				statusChanges++
			}
			prev = status
		}

		stability := 1.0
		if appearances > 1 {
			stability = 1.0 - float64(statusChanges)/float64(appearances-1)
		}

		classification := classifyTrendStep(statusChanges, firstStatus, lastStatus)
		switch classification {
		case "stable":
			stableCount++
		case "flaky":
			flakyCount++
		case "degrading":
			degradingCount++
		case "improving":
			improvingCount++
		}
		stabilitySum += stability

		stepTrends = append(stepTrends, trendStep{
			StepID:         id,
			Statuses:       statuses,
			FirstSeenIndex: firstSeenIndex,
			LastSeenIndex:  lastSeenIndex,
			StatusChanges:  statusChanges,
			Stability:      stability,
			Classification: classification,
		})
	}

	overallStability := 1.0
	if len(ids) > 0 {
		overallStability = stabilitySum / float64(len(ids))
	}

	return &trendOutput{
		TrendTimestamp: time.Now().UTC().Format(time.RFC3339),
		ReportCount:    reportCount,
		StepTrends:     stepTrends,
		Aggregate: trendAggregate{
			TotalStepsTracked: len(ids),
			StableCount:      stableCount,
			FlakyCount:       flakyCount,
			DegradingCount:   degradingCount,
			ImprovingCount:   improvingCount,
			OverallStability: overallStability,
		},
	}
}

func classifyTrendStep(statusChanges int, firstStatus, lastStatus string) string {
	if statusChanges == 0 {
		return "stable"
	}
	if statusChanges >= 2 {
		return "flaky"
	}

	firstRank := statusRank(firstStatus)
	lastRank := statusRank(lastStatus)
	if lastRank < firstRank {
		return "degrading"
	}
	if lastRank > firstRank {
		return "improving"
	}
	return "stable"
}

func statusRank(status string) int {
	switch status {
	case "PASS":
		return 4
	case "FAIL":
		return 3
	case "ERROR":
		return 2
	case "TIMEOUT":
		return 1
	case "SKIPPED":
		return 0
	default:
		return -1
	}
}

func printTrendText(output *trendOutput) {
	header := fmt.Sprintf("Trend Analysis (%d reports)", output.ReportCount)
	fmt.Println(header)
	fmt.Println(strings.Repeat("=", len(header)))

	for _, step := range output.StepTrends {
		statusParts := make([]string, 0, len(step.Statuses))
		for _, status := range step.Statuses {
			if status == nil {
				statusParts = append(statusParts, "-")
			} else {
				statusParts = append(statusParts, *status)
			}
		}
		fmt.Printf("%s  %s  [%s]  stability=%.2f\n", step.StepID, step.Classification, strings.Join(statusParts, ","), step.Stability)
	}

	fmt.Println("---")
	fmt.Printf("%d steps: %d stable, %d flaky, %d degrading, %d improving\n",
		output.Aggregate.TotalStepsTracked,
		output.Aggregate.StableCount,
		output.Aggregate.FlakyCount,
		output.Aggregate.DegradingCount,
		output.Aggregate.ImprovingCount)
	fmt.Printf("Overall stability: %.1f%%\n", output.Aggregate.OverallStability*100)
}
